return {["fb19_01"]={["dsc"]=[[你走在一条蜿蜒而上的山间小路上，这里十分荒凉，前面不远处就是一些小树林，南面就是通往襄阳城的青石大道，北面有条小路不知通向哪里。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_01]],["leftUp"]=[[fb19_02]],["name"]=[[山间小路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_02"]={["dsc"]=[[你走在一条蜿蜒而上的山间小路上，这里十分荒凉，前面不远处就是一些小树林，北面有条小路不知通向哪里。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_02]],["item1"]=[[fb19item13]],["item2"]=[[fb19zmdj]],["leftUp"]=[[fb19_03]],["name"]=[[山间小路]],["permission"]=1,["rightDown"]=[[fb19_01]],["role1"]=[[fb19r02_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_03"]={["dsc"]=[[你走在一条蜿蜒而上的山间小路上，这里十分荒凉，前面不远处就是一些小树林，北面有条小路好像通向一条小溪流。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_03]],["name"]=[[山间小路]],["permission"]=1,["rightDown"]=[[fb19_02]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_04]],["visible"]=1},["fb19_04"]={["down"]=[[fb19_03]],["dsc"]=[[你沿着山路前行数里，来到一条河边。朝阳初升，照得碧玉般的水面上犹如镶了一层黄金一般，壮丽无比，你站在这里，心中什么也不愿意想，只希望就这样天长地久，时间永恒。]],["enterable"]=1,["id"]=[[fb19_04]],["item1"]=[[fb19item6]],["item2"]=[[2019qxhdd1]],["name"]=[[河边]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_05]],["visible"]=1},["fb19_05"]={["down"]=[[fb19_04]],["dsc"]=[[这里两边山峰壁立，抬头望天，只余一线。山青水碧，景色极尽清幽，只是四下寂无声息，隐隐透著凶险，溪心有九块大石迎面耸立，犹如屏风一般，挡住了去路。]],["enterable"]=1,["id"]=[[fb19_05]],["name"]=[[独峰岭]],["permission"]=1,["role1"]=[[fb19r05_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_06]],["visible"]=1},["fb19_06"]={["down"]=[[fb19_05]],["dsc"]=[[这座亭子四角攥尖顶，檐角飞翘，四柱拱托，古拙而又精巧。山下弧形水渠环绕，水声潺潺，亭四周山石林立，千资百态。坐立亭中可望碧波滚滚，令人有临海观澜之感。]],["enterable"]=1,["id"]=[[fb19_06]],["item1"]=[[bfitem1]],["name"]=[[观澜亭]],["permission"]=1,["right"]=[[fb19_07]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_07"]={["dsc"]=[[榭为三间，东南北三面为敞选，中为明间，顶部平直，结构灵巧。榭下是就是引泉入池的渠道，上有响琴桥，当流水击石时，声若琴瑟。气爽风清，倒是个读书作画的好去处。]],["enterable"]=1,["id"]=[[fb19_07]],["item1"]=[[bfitem2]],["left"]=[[fb19_06]],["name"]=[[响琴榭]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_08]],["visible"]=1},["fb19_08"]={["down"]=[[fb19_07]],["dsc"]=[[这里似洞非洞，顶上崖檐覆出，石乳倒垂。浮者若飞霞，亘者若虹霓，豁然楼殿门阙，悬若铜鼓编磬，并有狮象蛟龙、莲荷阡陌、蜂房水涡之属。其下澄潭邃谷，幽深无底，四面茂盛古树参天，流水潆洄。]],["enterable"]=1,["id"]=[[fb19_08]],["item1"]=[[fb19item18]],["item2"]=[[ycitem8]],["name"]=[[飞云岩]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_09]],["visible"]=1},["fb19_09"]={["down"]=[[fb19_08]],["dsc"]=[[山径只有一条，倒不会走错，只见山径越走越高，也越是崎岖。旁边长着各种荆棘，在山石参差的环境之下，越发显得阴森可怖。而且，海拔越高，山风越是凌厉，吹得人双颊生疼。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_09]],["name"]=[[山径]],["permission"]=1,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_10]],["visible"]=1},["fb19_10"]={["down"]=[[fb19_09]],["dsc"]=[[山径只有一条，倒不会走错，只见山径越走越高，也越是崎岖。旁边长着各种荆棘，在山石参差的环境之下，越发显得阴森可怖。而且，海拔越高，山风越是凌厉，吹得人双颊生疼。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_10]],["name"]=[[山径]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_11]],["visible"]=1},["fb19_11"]={["down"]=[[fb19_10]],["dsc"]=[[山顶四周草木青翠欲滴，繁花似锦，一路上已是风物佳胜，此处更是个罕见的美景之地，信步而行，只见路旁仙鹤三二、白鹿成群，松鼠小兔，尽是见人不惊。东面一条山路不知通往何处，北面是一大片竹林。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_11]],["item1"]=[[ycitem4]],["left"]=[[fb19_12]],["name"]=[[山顶平地]],["permission"]=1,["right"]=[[fb19_13]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_18]],["visible"]=1},["fb19_12"]={["dsc"]=[[这是一座小石屋，四围是用大石块砌起来的。地上胡乱铺着几张草席，墙角放着一张桌子，看上去破烂不堪，桌上放着几只破碗。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb19_12]],["item1"]=[[fb19item3]],["item2"]=[[fb19item11]],["item3"]=[[fb19item12]],["name"]=[[小石屋]],["permission"]=2,["right"]=[[fb19_11]],["role1"]=[[fb19r12_1]],["role2"]=[[fb19r12_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_13"]={["dsc"]=[[此处是一条崎岖山路，你睁大了眼四下眺望，惟见云生谷底，雾迷峰巅，空山寂寂，微闻鸟语，天地茫茫，就只你一人而已。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_13]],["left"]=[[fb19_11]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb19_14]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_14"]={["dsc"]=[[此处是一条崎岖山路，你睁大了眼四下眺望，惟见云生谷底，雾迷峰巅，空山寂寂，微闻鸟语，天地茫茫，就只你一人而已。眼前出现两条岔路，你一时竟不知向哪一条走才是。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_14]],["item1"]=[[rybritem9]],["left"]=[[fb19_13]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb19_16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_15]],["visible"]=1},["fb19_15"]={["down"]=[[fb19_14]],["dsc"]=[[你游目四顾，原来处身于一个绝峰之顶，四下里林木茂密，远望石庄，相距已有数里之遥。你睁大了眼四下眺望，惟见云生谷底，雾迷峰巅，空山寂寂，微闻鸟语，天地茫茫，就只你一人而已。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_15]],["item1"]=[[ycitem1]],["name"]=[[厉鬼峰]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_16"]={["dsc"]=[[你不觉已到了谷东自来极少人行之处，抬头见一座山峰冲天而起，正是绝险之地的太行峰。这山峰峰腰处有一处山崖，不知若干年代之前有人在崖上刻了“太行崖”三字。山崖下临深渊，自渊口下望，黑黝黝的深不见底。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_16]],["item1"]=[[fb19item4]],["left"]=[[fb19_14]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb19_17]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_17"]={["dsc"]=[[这里是太行谷后山峰顶，人迹鲜至。那悬崖下临深谷，上面山峰笔立，峰顶深入云雾之中，不知尽头。“太行崖”前后风景清幽，只因地势实在太险，山石滑溜溜，极易掉入深渊，人们轻易不敢来此。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb19_17]],["item1"]=[[24maskjqcf01]],["left"]=[[fb19_16]],["name"]=[[太行崖]],["permission"]=2,["right"]=[[fb19_40]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_18"]={["down"]=[[fb19_11]],["dsc"]=[[行出数里路，忽见对面绿油油的好大一片竹林，北方很少见长得这般茂密的竹林，更别提数量之大，确实罕见，林中栖息着各种鸟儿，啼声婉转，多少添了点喜气，林子中有一条小路通往后山。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb19_18]],["item1"]=[[fb19item10]],["item2"]=[[fb19item10]],["item3"]=[[fb19item10]],["item4"]=[[ycitem2]],["left"]=[[fb19_18]],["name"]=[[竹林]],["permission"]=1,["right"]=[[fb19_18]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_19]],["visible"]=1},["fb19_19"]={["down"]=[[fb19_18]],["dsc"]=[[行出数里路，忽见对面绿油油的好大一片竹林，北方很少见长得这般茂密的竹林，更别提数量之大，确实罕见，林中栖息着各种鸟儿，啼声婉转，多少添了点喜气，林子中有一条小路通往后山。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb19_19]],["item1"]=[[fb19item10]],["item2"]=[[fb19item10]],["item3"]=[[fb19item10]],["item4"]=[[fb19item1]],["left"]=[[fb19_19]],["name"]=[[竹林]],["permission"]=1,["right"]=[[fb19_19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_20]],["visible"]=1},["fb19_20"]={["down"]=[[fb19_18]],["dsc"]=[[行出数里路，忽见对面绿油油的好大一片竹林，北方很少见长得这般茂密的竹林，更别提数量之大，确实罕见，林中栖息着各种鸟儿，啼声婉转，多少添了点喜气，林子中有一条小路通往后山。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb19_20]],["item1"]=[[fb19item10]],["item2"]=[[fb19item10]],["item3"]=[[fb19item10]],["left"]=[[fb19_21]],["name"]=[[竹林]],["permission"]=1,["right"]=[[fb19_20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_20]],["visible"]=1},["fb19_21"]={["down"]=[[fb19_18]],["dsc"]=[[行出数里路，忽见对面绿油油的好大一片竹林，北方很少见长得这般茂密的竹林，更别提数量之大，确实罕见，林中栖息着各种鸟儿，啼声婉转，多少添了点喜气，林子中有一条小路通往后山。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb19_21]],["item1"]=[[fb19item10]],["item2"]=[[fb19item10]],["item3"]=[[fb19item10]],["left"]=[[fb19_22]],["name"]=[[竹林]],["permission"]=1,["right"]=[[fb19_20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_20]],["visible"]=1},["fb19_22"]={["dsc"]=[[穿过竹林，突然一阵清香涌至，眼前无边无际的全是水仙花，原来地下是浅浅的一片水塘，深不逾尺，种满了水仙，这花是原是南方之物，不知何以竟会在关洛之间的山顶出现。]],["enterable"]=1,["id"]=[[fb19_22]],["item1"]=[[ycitem5]],["left"]=[[fb19_23]],["name"]=[[水塘]],["permission"]=1,["right"]=[[fb19_18]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_23"]={["dsc"]=[[对于走惯了泥土路的人来说，眼前这条青石板倒是很有意思，又湿又滑。在每块石板的间隙之中，长满了绿色的青苔。一只白鹤独足立于青石板上，不时地用嘴梳理着自己的毛羽，神情煞是可爱。北面隐约看出是一座大石屋。]],["enterable"]=1,["id"]=[[fb19_23]],["name"]=[[青石板路]],["permission"]=1,["right"]=[[fb19_22]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_24]],["visible"]=1},["fb19_24"]={["down"]=[[fb19_23]],["dsc"]=[[一座极大的石屋出现在眼前，只见两名绿衫僮儿手执拂尘，站在石屋门前。石屋二边是绝壁峭崖，几株长在绝壁上松树长得很茂盛，把石屋遮得严严实实的，远远看来，几乎看不出在这深谷中还有座石屋。]],["enterable"]=1,["id"]=[[fb19_24]],["item1"]=[[fb19item9]],["name"]=[[大石屋]],["permission"]=1,["role1"]=[[fb19r24_1]],["role2"]=[[fb19r24_2]],["role3"]=[[fb19r24_3]],["role4"]=[[fb19r24_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_25]],["visible"]=1},["fb19_25"]={["down"]=[[fb19_24]],["dsc"]=[[这里是太行谷的大厅，是公孙谷主会客的地方，大厅正前大梁上挂着一块大匾，上面刻着四个龙飞凤舞的金字，异常气派。主人又特地在大匾之下挂了一幅「白鹤鸣天」之图，画技精深，看得出其主特立独行的性格。]],["enterable"]=1,["id"]=[[fb19_25]],["name"]=[[大厅]],["permission"]=1,["role1"]=[[fb19r25_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_34]],["visible"]=1},["fb19_26"]={["down"]=[[fb19_28]],["dsc"]=[[转过几个弯后，已到西厢长廊的尽头。相对廊子的细窄而言，尽头的大水池令人顿觉豁然开朗，池子极大，周围圈以古色古香的砖瓦，再配以飘逸的柳条，有种仙境的意味。池中豢养的鱼儿浑身金灿灿的，活跃非常。]],["enterable"]=1,["id"]=[[fb19_26]],["name"]=[[西厢长廊]],["permission"]=2,["right"]=[[fb19_29]],["role1"]=[[fb19r26_1]],["role2"]=[[fb19r26_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_27]],["visible"]=1},["fb19_27"]={["down"]=[[fb19_26]],["dsc"]=[[这里是剑室，只见室中壁上、桌上、架上、柜中。几间，尽皆列满兵刃，式样繁多，十之八九都是古剑，或长逾七尺，或短仅数寸，有的铁口斑驳，有的寒光逼人。却见屋角西壁间一大片火烧的焦痕，几张桌椅也均烧得残破。]],["enterable"]=1,["id"]=[[fb19_27]],["name"]=[[剑室]],["permission"]=2,["role1"]=[[fb19r27_100]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_28"]={["dsc"]=[[鼻中闻到一股浓浓的泥土清香，这便是芝房，只见房内到处种植着奇花异草，房间中央种着一枝灵芝，看上去与普通的灵芝有些不一样，一名绿衫少女正守护着它。]],["enterable"]=1,["id"]=[[fb19_28]],["item1"]=[[ycitem6]],["item2"]=[[ycitem7]],["name"]=[[芝房]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_26]],["visible"]=1},["fb19_29"]={["down"]=[[fb19_31]],["dsc"]=[[西厢长廊短而精致，其右是景色秀丽的花圃，所种植的奇花异草更是惹人喜爱，引得蜂蜂蝶蝶都围着花儿忙个不停。其左是供休息的小巧座椅，配有精致的雕花扶手，整条廊子充满了勃勃生机。它的南北二侧是休息室。]],["enterable"]=1,["id"]=[[fb19_29]],["left"]=[[fb19_26]],["name"]=[[西厢长廊]],["permission"]=2,["right"]=[[fb19_32]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_30]],["visible"]=1},["fb19_30"]={["down"]=[[fb19_29]],["dsc"]=[[这是间整洁的厢房，因门窗常闭着，光线很昏暗。这是男弟子休息室，房里别无他物，只有中间放着几张收拾得舒舒服服的大床，床上还有一些棉被，看着就让人想睡觉。]],["enterable"]=1,["id"]=[[fb19_30]],["name"]=[[休息室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_31"]={["dsc"]=[[这是间整洁的厢房，因门窗常闭着，光线很昏暗。这是女弟子休息室，房里别无他物，只有中间放着几张收拾得舒舒服服的大床，床上还有一些棉被，看着就让人想睡觉。]],["enterable"]=1,["id"]=[[fb19_31]],["name"]=[[休息室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_29]],["visible"]=1},["fb19_32"]={["down"]=[[fb19_34]],["dsc"]=[[这是条幽静的长廊，两边均设着红色雕花扶栏，再配以白色的粉墙，显得十分素雅。尤其是挂在长廊檐下的水晶风铃，在微风的轻抚之下，洒出一阵阵细碎悦耳的玲声，令人遐思纷飞。此廊北通向花园，南通向后堂。]],["enterable"]=1,["id"]=[[fb19_32]],["left"]=[[fb19_29]],["name"]=[[长廊]],["permission"]=1,["right"]=[[fb19_35]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_33]],["visible"]=1},["fb19_33"]={["down"]=[[fb19_32]],["dsc"]=[[这里是花园，种满了情花树，西北方是一个小池塘，眼下正值六月，池塘内荷花都绽开了花朵，几只青蛙趴在荷叶上“呱呱”地叫个不停。西南方一座假山，南面是一条长廊。]],["enterable"]=1,["id"]=[[fb19_33]],["name"]=[[花园]],["permission"]=2,["role1"]=[[fb19r33_100]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_34"]={["down"]=[[fb19_25]],["dsc"]=[[这是后堂，借客人在这里歇息，南方一排屏风遮住了视线，绕过屏风就是一条密道直通大厅了。北面是一条长廊，直通往后花园。]],["enterable"]=1,["id"]=[[fb19_34]],["name"]=[[后堂]],["permission"]=1,["role1"]=[[fb19r34_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_32]],["visible"]=1},["fb19_35"]={["down"]=[[fb19_37]],["dsc"]=[[步入东厢长廊，扑面而来的就是一股药草的气味，原来是从北面的丹房散发出来的，那是主人最喜爱的地方，平时很少有人敢擅入。南面传来阵阵的吆喝声，这便是太行谷弟子练功房了。]],["enterable"]=1,["id"]=[[fb19_35]],["left"]=[[fb19_32]],["name"]=[[东厢长廊]],["permission"]=1,["right"]=[[fb19_38]],["role1"]=[[fb19r33_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_36]],["visible"]=1},["fb19_36"]={["down"]=[[fb19_35]],["dsc"]=[[你打量室中，只见桌上，柜中满列药瓶，壁上一丛丛的挂著无数乾草药，西首并列三座丹炉，这间石室自便是所谓丹房了。]],["enterable"]=1,["id"]=[[fb19_36]],["name"]=[[丹房]],["permission"]=1,["role1"]=[[fb19r36_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_37"]={["dsc"]=[[这里是练功房，地上放着几张蒲团，几名太行谷弟子在这里吐纳练功，练功房的四个角上各放着一只香炉，房内弥漫着一股淡淡的香气。]],["enterable"]=1,["id"]=[[fb19_37]],["name"]=[[练功房]],["permission"]=2,["role1"]=[[fb19r37_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_35]],["visible"]=1},["fb19_38"]={["dsc"]=[[这是东厢走廊尽头，东面通向书房，一般外派弟子到这里就止步，没有公孙谷主的命令，外派弟子不能进书房。]],["enterable"]=1,["id"]=[[fb19_38]],["left"]=[[fb19_35]],["name"]=[[东厢长廊]],["permission"]=2,["right"]=[[fb19_39]],["role1"]=[[fb19r38_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_39"]={["dsc"]=[[房内整齐地排着几排书架，左边的书架上排列着一些基本武功的书籍。右边的书架上排列着一些诗词。东首放着一张桌子，走近一看，桌上放着一些公孙谷主写的诗词。书房出去是东厢长廊。]],["enterable"]=1,["id"]=[[fb19_39]],["item1"]=[[fb19item16]],["left"]=[[fb19_38]],["name"]=[[书房]],["permission"]=2,["role1"]=[[fb19r39_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_40"]={["dsc"]=[[你来到山峰腰部的一处峭壁，岩壁上不知是谁刻得有几行大字，自此向上，数十丈光溜溜的寸草不生，终年云雾环绕，天风猛烈，即便是飞鸟也甚难在峰顶停足。山崖旁边就是一道深渊。悬崖边上长着一棵老松树斜斜的探出崖边。]],["enterable"]=1,["id"]=[[fb19_40]],["item1"]=[[ycitem3]],["left"]=[[fb19_17]],["name"]=[[峭壁]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_41"]={["dsc"]=[[这里黑漆漆的，你只觉得身子在水中不断往下潜沉，待沉势稍缓，拨水上升，刚钻出水面吸了几口气，突然鼻中闻到一股腥臭，同时左首水波激荡，似有甚麽巨大水族来袭。]],["enterable"]=1,["id"]=[[fb19_41]],["name"]=[[鳄鱼潭]],["permission"]=1,["right"]=[[fb19_42]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_42"]={["down"]=[[fb19_43]],["dsc"]=[[越过鳄鱼潭，见到一个洞口，里面漆黑一片，鼻中只隐约闻到一股刺鼻的气味。洞口极窄，看样子只得屈膝爬行了。]],["enterable"]=1,["id"]=[[fb19_42]],["left"]=[[fb19_41]],["name"]=[[洞口]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_43"]={["down"]=[[fb19_44]],["dsc"]=[[山洞里蜿蜒崎岖，绵延向下，由于鳄潭水气蒸浸，洞中潮湿滑溜，腥臭难闻。令人不寒而立。遑论是在毫无亮光的情况下，平添几份阴森的感觉。洞中极窄，根本站不起身来。]],["enterable"]=1,["id"]=[[fb19_43]],["name"]=[[山洞]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_42]],["visible"]=1},["fb19_44"]={["dsc"]=[[你爬行了一阵，隧洞渐宽，已可直立行走，行了良久，始终不到尽头，地下却越来越平。突然猛听得左首传来一阵大笑之声，这几下明明是笑声，听来却竟与嚎哭一般，语调异常的凄凉悲切。]],["enterable"]=1,["id"]=[[fb19_44]],["left"]=[[fb19_45]],["name"]=[[隧洞]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_43]],["visible"]=1},["fb19_45"]={["dsc"]=[[你转过二个弯后，眼前突然亮光耀目。这是一个天然生成的石窟，深不见尽头，顶上有个大孔，离地一百余丈。日光从孔中透射进来。抬头可以看见高处石壁上凹凹凸凸，不似底下的滑溜。石窟中日光所及处生长了不少大枣树。]],["enterable"]=1,["id"]=[[fb19_45]],["name"]=[[石窟]],["permission"]=1,["right"]=[[fb19_44]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_46]],["visible"]=1},["fb19_46"]={["down"]=[[fb19_45]],["dsc"]=[[你约莫爬了六七十丈，仗着轻功卓绝，一路化险为夷，但爬到离洞穴七八丈时，石壁不但光滑异常，再无可容手足之处，而且向内倾斜，除非是壁虎、苍蝇，方能附壁不落。]],["enterable"]=1,["id"]=[[fb19_46]],["item1"]=[[fb19item19]],["name"]=[[石壁]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb19_47"]={["dsc"]=[[这里是一个石室，旁边有一些石桌石椅，似乎之前有人居住过。]],["id"]=[[fb19_47]],["item1"]=[[wabaorenwu5]],["item2"]=[[wabaorenwu14]],["name"]=[[石室]],["permission"]=2,["right"]=[[fb19_48]],["stepMusic"]=[[jiaobu]]},["fb19_48"]={["dsc"]=[[这里是一个石室，旁边有一些石桌石椅，似乎之前有人居住过。]],["id"]=[[fb19_48]],["item1"]=[[wabaorenwu19]],["left"]=[[fb19_47]],["name"]=[[石室]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb19_49"]={["down"]=[[fb19_50]],["dsc"]=[[越走越偏僻的一条山路，前面杂草丛生，已经没过了膝盖。四周有不少踩踏的痕迹，似乎有人从这里经过。]],["id"]=[[fb19_49]],["name"]=[[山路]],["permission"]=2,["role1"]=[[rybritem2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_14]]},["fb19_50"]={["down"]=[[fb19_51]],["dsc"]=[[山路旁藏在荒草之中的一条密径。密径蜿蜒曲折，一路延伸到荒草深处。不远处丛林茂密，隐隐有雾气升腾。]],["id"]=[[fb19_50]],["name"]=[[密径]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb19_49]]},["fb19_51"]={["down"]=[[fb19_53]],["dsc"]=[[山路旁藏在荒草之中的一条密径。密径蜿蜒曲折，一路延伸到荒草深处。不远处丛林茂密，隐隐有雾气升腾。]],["id"]=[[fb19_51]],["name"]=[[密径]],["permission"]=2,["role1"]=[[rybrr51_01]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_50]]},["fb19_52"]={["down"]=[[fb19_53]],["dsc"]=[[一片茂密的树林，树林之中常年雾气萦绕，如置身仙境，但也让人难以分清方向。]],["id"]=[[fb19_52]],["item1"]=[[rybritem8]],["item2"]=[[rybritem8]],["item3"]=[[rybritem8]],["item4"]=[[rybritem8]],["left"]=[[fb19_53]],["name"]=[[迷雾林]],["permission"]=2,["right"]=[[fb19_53]],["role1"]=[[rybritem8]],["role2"]=[[rybritem8]],["role3"]=[[rybritem8]],["role4"]=[[rybritem8]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_53]]},["fb19_53"]={["down"]=[[fb19_54]],["dsc"]=[[一片茂密的树林，树林之中常年雾气萦绕，如置身仙境，但也让人难以分清方向。]],["id"]=[[fb19_53]],["item1"]=[[rybritem8]],["item2"]=[[rybritem8]],["item3"]=[[rybritem8]],["item4"]=[[rybritem8]],["left"]=[[fb19_52]],["name"]=[[迷雾林]],["permission"]=2,["right"]=[[fb19_52]],["role1"]=[[rybritem8]],["role2"]=[[rybritem8]],["role3"]=[[rybritem8]],["role4"]=[[rybritem8]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_52]]},["fb19_54"]={["down"]=[[fb19_52]],["dsc"]=[[一片茂密的树林，树林之中常年雾气萦绕，如置身仙境，但也让人难以分清方向。]],["id"]=[[fb19_54]],["item1"]=[[rybritem8]],["item2"]=[[rybritem8]],["item3"]=[[rybritem8]],["item4"]=[[rybritem8]],["left"]=[[fb19_55]],["name"]=[[迷雾林]],["permission"]=2,["right"]=[[fb19_52]],["role1"]=[[rybritem8]],["role2"]=[[rybritem8]],["role3"]=[[rybritem8]],["role4"]=[[rybritem8]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_52]]},["fb19_55"]={["down"]=[[fb19_52]],["dsc"]=[[一片茂密的树林，树林之中常年雾气萦绕，如置身仙境，但也让人难以分清方向。]],["id"]=[[fb19_