={["dsc"]=[[这里是祭祀日神尧白的场所。尧白是重光教所崇拜的太阳之神，以男子之身现世，赋予人世生命，他的光芒普照大地，万物沐浴阳光之后，便能获得生机。]],["id"]=[[fb19_61]],["name"]=[[日坛]],["permission"]=2,["right"]=[[fb19_62]],["role1"]=[[rybritem4]],["stepMusic"]=[[jiaobu]]},["fb19_62"]={["down"]=[[fb19_65]],["dsc"]=[[一个不大的广场，广场修建的十分平整。两旁设有石凳，可供人休息。]],["id"]=[[fb19_62]],["left"]=[[fb19_61]],["name"]=[[广场]],["permission"]=2,["right"]=[[fb19_63]],["role1"]=[[rybrr62_01]],["role2"]=[[rybrr62_02]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_59]]},["fb19_63"]={["dsc"]=[[这里是祭祀月神谦和的场所。谦和是重光教所崇拜的月亮之神，以女子之身现世，赋予人世情感，柔和的月光倾洒大地，万物便能获得灵性。]],["id"]=[[fb19_63]],["left"]=[[fb19_62]],["name"]=[[月坛]],["permission"]=2,["role1"]=[[rybrr63_01]],["role2"]=[[rybritem5]],["stepMusic"]=[[jiaobu]]},["fb19_64"]={["dsc"]=[[这里是一个种满各种花草的花园。这里花香四溢，蜂蝶飞舞，两头小鹿正在其中嬉戏玩耍，见你接近也不害怕，用鼻尖轻轻触碰到你的手之后便围绕着你蹦跳，十分可爱。]],["id"]=[[fb19_64]],["leftDown"]=[[fb19_66]],["name"]=[[百花间]],["permission"]=2,["role1"]=[[rybrr64_01]],["role2"]=[[rybritem7]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_60]]},["fb19_65"]={["dsc"]=[[重光分舵的正殿，是侍从商议大事的场所。正殿修建十分气派，左右梁柱之上各自雕刻着日月之神，正中红毯铺地，踩上去十分柔软。正殿深处是侍从的宝座，由纯银打造而成，雕工精致，侍从平时便在宝座之上传播教义。]],["id"]=[[fb19_65]],["name"]=[[正殿]],["permission"]=2,["right"]=[[fb19_66]],["role1"]=[[rybrr65_01]],["role2"]=[[rybrr65_02]],["stepMusic"]=[[jiaobu]],["up"]=[[fb19_62]]},["fb19_66"]={["dsc"]=[[一棵巨大的中空树设置成的树屋。树屋之中飘散着木头的香气。屋内陈设朴素整齐，床柜桌椅一应俱全，从摆放之物来看，似是女子闺房。房屋之后有一道小门，小门外正是百花间。]],["id"]=[[fb19_66]],["left"]=[[fb19_65]],["name"]=[[树屋]],["permission"]=2,["rightUp"]=[[fb19_64]],["role1"]=[[rybritem6]],["stepMusic"]=[[jiaobu]]}}000000